341	/// 这个模块包含调用系统调用的最小封装，用户可以直接使用这些函数调用自定义的系统调用。
342	///
343	/// # Safety
344	///
345	/// 所有 syscall 函数都是 unsafe 的，因为：
346	/// - 它们直接执行 `ecall` 指令触发系统调用
347	/// - 调用者需要确保参数符合对应系统调用的要求
348	/// - 传递无效的指针或参数可能导致未定义行为
349	#[cfg(target_arch = "riscv64")]
350	pub mod native {
351	    use crate::SyscallId;
352	    use core::arch::asm;
353	
354	    /// 执行无参数的系统调用。
355	    ///
356	    /// # Safety
357	    ///
358	    /// 调用者必须确保 `id` 是有效的系统调用号。
359	    #[inline(always)]
360	    pub unsafe fn syscall0(id: SyscallId) -> isize {
361	        let ret: isize;
362	        // SAFETY: ecall 指令触发系统调用，由内核处理
363	        unsafe {
364	            asm!("ecall",
365	                in("a7") id.0,
366	                out("a0") ret,
367	            );
368	        }
369	        ret
370	    }
371	
372	    /// 执行带 1 个参数的系统调用。
373	    ///
374	    /// # Safety
375	    ///
376	    /// 调用者必须确保 `id` 是有效的系统调用号，且 `a0` 符合该系统调用的参数要求。
377	    #[inline(always)]
378	    pub unsafe fn syscall1(id: SyscallId, a0: usize) -> isize {
379	        let ret: isize;
380	        // SAFETY: ecall 指令触发系统调用，由内核处理
381	        unsafe {
382	            asm!("ecall",
383	                inlateout("a0") a0 => ret,
384	                in("a7") id.0,
385	            );
386	        }
387	        ret
388	    }
389	
390	    /// 执行带 2 个参数的系统调用。
391	    ///
392	    /// # Safety
393	    ///
394	    /// 调用者必须确保 `id` 是有效的系统调用号，且参数符合该系统调用的要求。
395	    #[inline(always)]
396	    pub unsafe fn syscall2(id: SyscallId, a0: usize, a1: usize) -> isize {
397	        let ret: isize;
398	        // SAFETY: ecall 指令触发系统调用，由内核处理
399	        unsafe {
400	            asm!("ecall",
401	                in("a7") id.0,
402	                inlateout("a0") a0 => ret,
403	                in("a1") a1,
404	            );
405	        }
406	        ret
407	    }
408	
409	    /// 执行带 3 个参数的系统调用。
410	    ///
411	    /// # Safety
412	    ///
413	    /// 调用者必须确保 `id` 是有效的系统调用号，且参数符合该系统调用的要求。
414	    #[inline(always)]
415	    pub unsafe fn syscall3(id: SyscallId, a0: usize, a1: usize, a2: usize) -> isize {
416	        let ret: isize;
417	        // SAFETY: ecall 指令触发系统调用，由内核处理
418	        unsafe {
419	            asm!("ecall",
420	                in("a7") id.0,
421	                inlateout("a0") a0 => ret,
422	                in("a1") a1,
423	                in("a2") a2,
424	            );
425	        }
426	        ret
427	    }
428	
429	    /// 执行带 4 个参数的系统调用。
430	    ///
431	    /// # Safety
432	    ///
433	    /// 调用者必须确保 `id` 是有效的系统调用号，且参数符合该系统调用的要求。
434	    #[inline(always)]
435	    pub unsafe fn syscall4(id: SyscallId, a0: usize, a1: usize, a2: usize, a3: usize) -> isize {
436	        let ret: isize;
437	        // SAFETY: ecall 指令触发系统调用，由内核处理
438	        unsafe {
439	            asm!("ecall",
440	                in("a7") id.0,
441	                inlateout("a0") a0 => ret,
442	                in("a1") a1,
443	                in("a2") a2,
444	                in("a3") a3,
445	            );
446	        }
447	        ret
448	    }
449	
450	    /// 执行带 5 个参数的系统调用。
451	    ///
452	    /// # Safety
453	    ///
454	    /// 调用者必须确保 `id` 是有效的系统调用号，且参数符合该系统调用的要求。
455	    #[inline(always)]
456	    pub unsafe fn syscall5(
457	        id: SyscallId,
458	        a0: usize,
459	        a1: usize,
460	        a2: usize,
461	        a3: usize,
462	        a4: usize,
463	    ) -> isize {
464	        let ret: isize;
465	        // SAFETY: ecall 指令触发系统调用，由内核处理
466	        unsafe {
467	            asm!("ecall",
468	                in("a7") id.0,
469	                inlateout("a0") a0 => ret,
470	                in("a1") a1,
471	                in("a2") a2,
472	                in("a3") a3,
473	                in("a4") a4,
474	            );
475	        }
476	        ret
477	    }
478	
479	    /// 执行带 6 个参数的系统调用。
480	    ///
481	    /// # Safety
