20	    println!("cargo:rerun-if-env-changed=LOG");
21	    println!("cargo:rerun-if-env-changed=TG_USER_DIR");
22	    println!("cargo:rerun-if-env-changed=TG_USER_CRATE");
23	    println!("cargo:rerun-if-env-changed=TG_USER_LOCAL_DIR");
