44	    let manifest_dir = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
45	    let manifest_dir = manifest_dir.to_string_lossy();
46	    manifest_dir.contains("/target/package/") || manifest_dir.contains("\\target\\package\\")
