49	fn write_linker() {
50	    let ld = PathBuf::from(env::var_os("OUT_DIR").unwrap()).join("linker.ld");
51	    fs::write(&ld, tg_linker::NOBIOS_SCRIPT).unwrap_or_else(|err| {
