57	fn build_apps() {
58	    let tg_user_root = ensure_tg_user();
59	    let cases_path = tg_user_root.join("cases.toml");
60	    println!("cargo:rerun-if-changed={}", cases_path.display());
61	    println!("cargo:rerun-if-changed={}", tg_user_root.join("Cargo.toml").display());
62	    println!("cargo:rerun-if-changed={}", tg_user_root.join("src").display());
63	
64	    let cfg = fs::read_to_string(&cases_path).unwrap_or_else(|err| {
65	        panic!("failed to read cases.toml from {}: {}", cases_path.display(), err)
66	    });
67	    let mut cases_map: HashMap<String, Cases> = toml::from_str(&cfg).unwrap_or_else(|err| {
68	        panic!("failed to parse cases.toml: {err}")
69	    });
70	
71	    let cases = cases_map.remove("ch2").unwrap_or_default();
72	    let base = cases.base.unwrap_or(0);
73	    let step = cases.step.unwrap_or(0);
74	    let names = cases.cases.unwrap_or_default();
75	
76	    if names.is_empty() {
77	        panic!("no user cases found for ch2 in {}", cases_path.display());
78	    }
79	
80	    let target_dir = tg_user_root.join("target").join(TARGET_ARCH).join("debug");
81	    let mut bins: Vec<PathBuf> = Vec::with_capacity(names.len());
82	
83	    for (i, name) in names.iter().enumerate() {
84	        let base_address = base + i as u64 * step;
85	        build_user_app(&tg_user_root, name, base_address);
86	        let elf = target_dir.join(name);
87	        let app_path = if base_address != 0 {
88	            objcopy_to_bin(&elf)
89	        } else {
90	            elf
91	        };
92	        bins.push(app_path);
93	    }
94	
95	    let out_dir = PathBuf::from(env::var_os("OUT_DIR").unwrap());
96	    let app_asm = out_dir.join("app.asm");
97	    write_app_asm(&app_asm, base, step, &bins);
98	    println!("cargo:rustc-env=APP_ASM={}", app_asm.display());
99	}
