101	fn build_user_app(tg_user_root: &PathBuf, name: &str, base_address: u64) {
102	    let mut cmd = Command::new("cargo");
103	    cmd.args([
104	        "build",
105	        "--manifest-path",
106	        tg_user_root.join("Cargo.toml").to_string_lossy().as_ref(),
107	        "--bin",
108	        name,
109	        "--target",
110	        TARGET_ARCH,
111	    ]);
112	
113	    if base_address != 0 {
114	        cmd.env("BASE_ADDRESS", base_address.to_string());
115	    }
116	
117	    let status = cmd.status().expect("failed to execute cargo build for user app");
118	    if !status.success() {
119	        panic!("failed to build user app {name}");
120	    }
121	}
