123	fn objcopy_to_bin(elf: &PathBuf) -> PathBuf {
124	    let bin = elf.with_extension("bin");
125	    let status = Command::new("rust-objcopy")
126	        .args([
127	            elf.to_string_lossy().as_ref(),
128	            "--strip-all",
129	            "-O",
130	            "binary",
131	            bin.to_string_lossy().as_ref(),
132	        ])
133	        .status()
134	        .expect("failed to execute rust-objcopy");
135	    if !status.success() {
136	        panic!("rust-objcopy failed for {}", elf.display());
137	    }
138	    bin
139	}
