141	fn write_app_asm(path: &PathBuf, base: u64, step: u64, bins: &[PathBuf]) {
142	    use std::io::Write;
143	    let mut asm = fs::File::create(path)
144	        .unwrap_or_else(|err| panic!("failed to create {}: {}", path.display(), err));
145	
146	    writeln!(
147	        asm,
148	        "\
149	.global apps
150	.section .data
151	.align 3
152	apps:
153	    .quad {base:#x}
154	    .quad {step:#x}
155	    .quad {}",
156	        bins.len(),
157	    )
158	    .unwrap();
159	
160	    for i in 0..bins.len() {
161	        writeln!(asm, "    .quad app_{i}_start").unwrap();
162	    }
163	
164	    writeln!(asm, "    .quad app_{}_end", bins.len() - 1).unwrap();
165	
166	    for (i, path) in bins.iter().enumerate() {
167	        writeln!(
168	            asm,
169	            "\
170	app_{i}_start:
171	    .incbin {path:?}
172	app_{i}_end:",
173	        )
174	        .unwrap();
175	    }
176	}
