203	fn ensure_tg_user() -> PathBuf {
204	    // 优先使用 TG_USER_DIR 显式指定的目录
205	    if let Ok(dir) = env::var("TG_USER_DIR") {
206	        let path = PathBuf::from(dir);
207	        if path.join("Cargo.toml").exists() {
208	            return path;
209	        }
210	    }
211	
212	    // 从 .cargo/config.toml [env] 读取三个配置项
213	    let crate_name = env::var("TG_USER_CRATE")
214	        .expect("TG_USER_CRATE not set; add it to .cargo/config.toml [env]");
215	    let local_dir_name = env::var("TG_USER_LOCAL_DIR")
216	        .expect("TG_USER_LOCAL_DIR not set; add it to .cargo/config.toml [env]");
217	    let version = env::var("TG_USER_VERSION")
218	        .expect("TG_USER_VERSION not set; add it to .cargo/config.toml [env]");
219	
220	    let manifest_dir = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
221	    let tg_user_dir = manifest_dir.join(&local_dir_name);
222	
223	    // 本地缓存目录已存在则直接使用
224	    if tg_user_dir.join("Cargo.toml").exists() {
225	        ensure_workspace_table(&tg_user_dir);
226	        return tg_user_dir;
227	    }
228	
229	    // 从 crates.io 克隆指定包
230	    let crate_spec = format!("{crate_name}@{version}");
231	    let status = Command::new("cargo")
232	        .args([
233	            "clone",
234	            crate_spec.as_str(),
235	            "--",
236	            tg_user_dir.to_string_lossy().as_ref(),
237	        ])
238	        .status()
239	        .unwrap_or_else(|e| panic!("failed to execute cargo clone {crate_spec}: {e}"));
240	
241	    if !status.success() {
242	        panic!(
243	            "failed to clone {crate_spec} into {}; ensure cargo-clone is installed or set TG_USER_DIR",
244	            tg_user_dir.display()
245	        );
246	    }
247	
248	    if !tg_user_dir.join("Cargo.toml").exists() {
249	        panic!(
250	            "{crate_spec} clone did not produce a valid crate at {}",
251	            tg_user_dir.display()
252	        );
253	    }
254	
255	    // 克隆后补加 [workspace]，防止父 workspace 将其识别为非成员而报错
256	    ensure_workspace_table(&tg_user_dir);
257	
258	    tg_user_dir
259	}
