261	/// 若 Cargo.toml 末尾尚无 [workspace] 表，则追加一个空的，
262	/// 使该 crate 成为独立 workspace 根，避免父 workspace 冲突。
263	fn ensure_workspace_table(dir: &PathBuf) {
264	    let cargo_toml = dir.join("Cargo.toml");
265	    let content = fs::read_to_string(&cargo_toml).unwrap_or_default();
266	    if !content.contains("[workspace]") {
267	        fs::write(&cargo_toml, format!("{}\n[workspace]\n", content))
268	            .unwrap_or_else(|err| panic!("failed to patch Cargo.toml in {}: {}", dir.display(), err));
269	    }
270	}
