74	use buddy_system_allocator::LockedHeap;
75	#[global_allocator]
76	static HEAP_ALLOCATOR: LockedHeap<32> = LockedHeap::empty();
77	static mut HEAP_SPACE: [u8; 0x400000] = [0; 0x400000];
78	
79	mod tangram;
80	mod gpu;
81	use gpu::VirtioHal;
