27	        let c = getchar();
28	        match c {
29	            LF | CR => {
30	                // 换行
31	                println!();
32	                if !line.is_empty() {
33	                    let pid = fork();
34	                    if pid == 0 {
35	                        // child process
36	                        // 子进程通过 exec 覆盖自身映像执行新程序。
37	                        if exec(line.as_str()) == -1 {
38	                            println!("Error when executing!");
39	                            return -4;
40	                        }
41	                        unreachable!();
42	                    } else {
43	                        // 父进程等待子进程完成，打印退出信息。
44	                        let mut exit_code: i32 = 0;
45	                        let exit_pid = waitpid(pid as isize, &mut exit_code);
46	                        assert_eq!(pid, exit_pid);
47	                        println!("Shell: Process {} exited with code {}", pid, exit_code);
48	                    }
49	                    line.clear();
50	                }

